import { test, expect } from '@playwright/test';

test.describe('Comment on Record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully add a comment to a record', async ({ page }) => {
    // Locate and click on a record to open details
    const recordItem = page.getByRole('button', { name: /record 1/i });
    await recordItem.click();

    // Verify record details are visible
    const recordTitle = page.getByRole('heading', { name: /record 1/i });
    await expect(recordTitle).toBeVisible();

    // Locate and click the comment button
    const commentButton = page.getByRole('button', { name: /add comment/i });
    await commentButton.click();

    // Verify comment form is visible
    const commentForm = page.getByRole('form', { name: /add comment/i });
    await expect(commentForm).toBeVisible();

    // Locate and fill in the comment textarea
    const commentTextarea = page.getByLabel(/comment/i);
    await commentTextarea.fill('This is a test comment for record 1');

    // Locate and click the submit button
    const submitButton = page.getByRole('button', { name: /submit comment/i });
    await submitButton.click();

    // Wait for comment to be added
    await page.waitForResponse(response => 
      response.url().includes('/api/comments') && response.status() === 201
    );

    // Verify success message appears
    const successMessage = page.getByText(/comment added successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify comment is displayed in the comment list
    const commentList = page.getByRole('region', { name: /comments/i });
    const addedComment = page.getByText('This is a test comment for record 1');
    await expect(addedComment).toBeVisible();
  });

  test('should display error when submitting an empty comment', async ({ page }) => {
    // Locate and click on a record to open details
    const recordItem = page.getByRole('button', { name: /record 2/i });
    await recordItem.click();

    // Verify record details are visible
    const recordTitle = page.getByRole('heading', { name: /record 2/i });
    await expect(recordTitle).toBeVisible();

    // Locate and click the comment button
    const commentButton = page.getByRole('button', { name: /add comment/i });
    await commentButton.click();

    // Verify comment form is visible
    const commentForm = page.getByRole('form', { name: /add comment/i });
    await expect(commentForm).toBeVisible();

    // Verify comment textarea is empty
    const commentTextarea = page.getByLabel(/comment/i);
    await expect(commentTextarea).toHaveValue('');

    // Locate and click the submit button without filling the textarea
    const submitButton = page.getByRole('button', { name: /submit comment/i });
    await submitButton.click();

    // Wait for error response
    await page.waitForResponse(response => 
      response.url().includes('/api/comments') && response.status() === 420
    );

    // Verify error message appears
    const errorMessage = page.getByText(/comment cannot be empty/i);
    await expect(errorMessage).toBeVisible();

    // Verify comment list remains unchanged
    const commentList = page.getByRole('region', { name: /comments/i });
    const existingComment = page.getByText(/this is an existing comment/i);
    await expect(existingComment).toBeVisible();
  });
});
